#!/usr/bin/env python3
from pathlib import Path
import sys
import xml.etree.ElementTree as ET

SOURCE = Path("/workspace/Quarterly_Brief_Source.fodt")
REFERENCE = Path("/tests/source_reference.fodt")
OUTPUT = Path("/home/user/Desktop/Q3_Operations_Brief.fodt")
REWARD = Path("/logs/verifier/reward.txt")
NS = {"office":"urn:oasis:names:tc:opendocument:xmlns:office:1.0", "style":"urn:oasis:names:tc:opendocument:xmlns:style:1.0", "text":"urn:oasis:names:tc:opendocument:xmlns:text:1.0", "fo":"urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0"}
def qn(p, n): return f"{{{NS[p]}}}{n}"
def finish(value, messages):
    REWARD.write_text(f"{value:.2f}\n")
    for message in messages: print(message, file=sys.stderr)
    raise SystemExit(0)

if not SOURCE.is_file() or SOURCE.read_bytes() != REFERENCE.read_bytes():
    finish(0.0, ["Source integrity failed: the distributed input was modified or removed."])
if not OUTPUT.is_file() or OUTPUT.stat().st_size == 0:
    finish(0.0, ["No saved Writer document exists at the required output path."])
try: root = ET.parse(OUTPUT).getroot()
except Exception as exc: finish(0.0, [f"Output is not parseable Flat XML ODF: {exc}"])

styles = {n.get(qn("style","name")):n for n in root.findall(".//style:style", NS) if n.get(qn("style","name"))}
def chain(name):
    seen=set()
    while name and name not in seen and name in styles:
        seen.add(name); node=styles[name]; yield node
        name=node.get(qn("style","parent-style-name"))
def has_style(p, display):
    internal=display.replace(" ", "_20_")
    return any(n.get(qn("style","display-name")) == display or n.get(qn("style","name")) == internal for n in chain(p.get(qn("text","style-name"),"")))
def centered(p):
    for n in chain(p.get(qn("text","style-name"),"")):
        props=n.find("style:paragraph-properties",NS)
        if props is not None and props.get(qn("fo","text-align")): return props.get(qn("fo","text-align")) == "center"
    return False
def bold(name):
    for n in chain(name):
        props=n.find("style:text-properties",NS)
        if props is not None and props.get(qn("fo","font-weight")) in {"bold","700","800","900"}: return True
    return False

body_text=root.find(".//office:body/office:text",NS)
paras=[] if body_text is None else [n for n in body_text.iter() if n.tag in {qn("text","p"),qn("text","h")}]
texts=["".join(p.itertext()) for p in paras]
expected=["Q3 Operations Brief","Prepared for the Operations Leadership Team","Highlights","Revenue grew 8% quarter over quarter.","Support improved customer response time by 17%.","Fulfillment reduced late shipments to 2.4%."]
title=next((p for p,t in zip(paras,texts) if t==expected[0]),None)
heading=next((p for p,t in zip(paras,texts) if t=="Highlights"),None)
support=next((p for p,t in zip(paras,texts) if t.startswith("Support improved")),None)
phrase_ok=False
if support is not None:
    spans=support.findall(".//text:span",NS)
    requested=[s for s in spans if "".join(s.itertext())=="customer response time" and bold(s.get(qn("text","style-name"),""))]
    other_bold=[s for s in spans if "".join(s.itertext())!="customer response time" and bold(s.get(qn("text","style-name"),""))]
    phrase_ok=len(requested)==1 and not other_bold and not bold(support.get(qn("text","style-name"),""))
checks=[(texts==expected,"wording and paragraph order"),(title is not None and has_style(title,"Heading 1") and centered(title),"centered Heading 1 title"),(heading is not None and has_style(heading,"Heading 2"),"Heading 2 label"),(phrase_ok,"bold phrase")]
for passed,label in checks: print(("PASS: " if passed else "FAIL: ")+label,file=sys.stderr)
finish(sum(int(p) for p,_ in checks)/len(checks),[])
